CREATE TABLE IF NOT EXISTS saia_measurement_drafts (id serial PRIMARY KEY,owner_id text NOT NULL,entitlement_id integer,capture_token text NOT NULL,provider_person_id text,status text NOT NULL DEFAULT 'pending',target_unit text NOT NULL DEFAULT 'cm',measurements jsonb,source_dimensions jsonb,error_code text,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS saia_drafts_capture_token_unique ON saia_measurement_drafts(capture_token);
CREATE UNIQUE INDEX IF NOT EXISTS saia_drafts_owner_person_unique ON saia_measurement_drafts(owner_id,provider_person_id);
CREATE TABLE IF NOT EXISTS measurement_source_snapshots (id serial PRIMARY KEY,owner_id text NOT NULL,source text NOT NULL,source_metadata jsonb NOT NULL,raw_dimensions jsonb NOT NULL,canonical_dimensions jsonb NOT NULL,created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scan_service_payments (id serial PRIMARY KEY,owner_id text NOT NULL,draft_id text NOT NULL,revision integer NOT NULL,checkout_key text NOT NULL,checkout_fingerprint text NOT NULL,stripe_payment_intent_id text,status text NOT NULL DEFAULT 'payment_pending',amount_cents integer NOT NULL,currency text NOT NULL DEFAULT 'usd',created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS scan_payments_owner_checkout_unique ON scan_service_payments(owner_id,checkout_key);
CREATE UNIQUE INDEX IF NOT EXISTS scan_payments_intent_unique ON scan_service_payments(stripe_payment_intent_id);
CREATE TABLE IF NOT EXISTS scan_entitlements (id serial PRIMARY KEY,owner_id text NOT NULL,payment_id integer NOT NULL,draft_id text NOT NULL,revision integer NOT NULL,status text NOT NULL DEFAULT 'authorized',retry_count integer NOT NULL DEFAULT 0,granted_by_admin_id text,consumed_at timestamp,completed_at timestamp,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS scan_entitlements_payment_unique ON scan_entitlements(payment_id);
CREATE TABLE IF NOT EXISTS garment_credits (id serial PRIMARY KEY,owner_id text NOT NULL,payment_id integer NOT NULL,amount_cents integer NOT NULL,currency text NOT NULL DEFAULT 'usd',status text NOT NULL DEFAULT 'available',reservation_key text,reserved_order_id text,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS garment_credits_payment_unique ON garment_credits(payment_id);
CREATE TABLE IF NOT EXISTS stripe_webhook_events (id text PRIMARY KEY,event_type text NOT NULL,created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scan_attempt_events (id serial PRIMARY KEY,entitlement_id integer NOT NULL,owner_id text NOT NULL,event_type text NOT NULL,actor_id text NOT NULL,metadata jsonb,created_at timestamp NOT NULL DEFAULT now());
